const paperConsumedProduction = Number(PaperConsumedProduction?.value ?? 0);
const productFoldLength = Number(ProductFoldLength?.value ?? 0);
const productPerFold = Number(ProductPerFold?.value ?? 0);
const productTotalCountPath = ProductTotalCount?.path ?? "";

if (!productTotalCountPath) {
  send(msg);
  return;
}

let productTotalCount = 0;
if (productFoldLength > 0 && productPerFold > 0) {
  productTotalCount = (paperConsumedProduction / productFoldLength) * productPerFold;
}

productTotalCount = Number(productTotalCount.toFixed(2));

await asset.set(productTotalCountPath, productTotalCount);

msg.payload = { productTotalCount, paperConsumedProduction, productFoldLength, productPerFold };

send(msg);

const raw = Number(EncoderRawValue?.value ?? 0);
const prevRaw = Number(EncoderPrevRaw?.value ?? 0);
const prevRawPath = EncoderPrevRaw?.path ?? "";
const machineSpeedPath = MachineSpeed?.path ?? "";
const setupPath = PaperConsumedSetup?.path ?? "";
const idlePath = PaperConsumedIdle?.path ?? "";
const prodPath = PaperConsumedProduction?.path ?? "";
const wastePath = PaperWaste?.path ?? "";
const totalConsumedPath = PaperTotalConsumed?.path ?? "";
const workOrderPath = "Jasuindo.OffsetPrinter.Taiyo1.Work Order";
const categoryPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Category";
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Alarm";
const assetPath = "Jasuindo.OffsetPrinter.Taiyo1";
const workOrder = String(asset.get(workOrderPath, "") ?? "").trim();

if (!prevRawPath) {
  send(msg);
  return;
}

const delta = raw >= prevRaw ? (raw - prevRaw) : raw;
if (!Number.isFinite(delta) || delta < 0) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

const speedMpm = delta * 0.6;
if (machineSpeedPath) {
  await asset.set(machineSpeedPath, speedMpm);
}

let activeCategory = "-";
let activeCategories = [];

if (workOrder && workOrder !== "-") {
  const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

if (delta === 0 || activeCategories.length !== 1) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

const setupPrev = Number(PaperConsumedSetup?.value ?? 0);
const idlePrev = Number(PaperConsumedIdle?.value ?? 0);
const prodPrev = Number(PaperConsumedProduction?.value ?? 0);

let setupNew = setupPrev;
let idleNew = idlePrev;
let prodNew = prodPrev;

if (activeCategory === "Setup") setupNew += delta / 100;
else if (activeCategory === "Idle") idleNew += delta / 100;
else if (activeCategory === "Production") prodNew += delta / 100;

if (setupPath) await asset.set(setupPath, setupNew);
if (idlePath) await asset.set(idlePath, idleNew);
if (prodPath) await asset.set(prodPath, prodNew);

const waste = setupNew + idleNew;
const totalConsumed = waste + prodNew;

if (wastePath) await asset.set(wastePath, waste);
if (totalConsumedPath) await asset.set(totalConsumedPath, totalConsumed);

await asset.set(prevRawPath, raw);

send(msg);

const setupPath = SetupDurationSec?.path ?? "";
const idlePath = IdleDurationSec?.path ?? "";
const prodPath = ProductionDurationSec?.path ?? "";
const runningHourPath = RunningHour?.path ?? "";
const workOrderPath = "Jasuindo.OffsetPrinter.Taiyo1.Work Order";
const categoryPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Category";
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Alarm";
const assetPath = "Jasuindo.OffsetPrinter.Taiyo1";
const workOrder = String(asset.get(workOrderPath, "") ?? "").trim();

if (!setupPath || !idlePath || !prodPath || !runningHourPath) {
  send(msg);
  return;
}

let setupTime = Number(SetupDurationSec?.value ?? 0);
let idleTime = Number(IdleDurationSec?.value ?? 0);
let prodTime = Number(ProductionDurationSec?.value ?? 0);
let runningHour = Number(RunningHour?.value ?? 0);

let activeCategory = "-";
let activeCategories = [];

if (workOrder && workOrder !== "-") {
  const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

if (activeCategory === "Setup") setupTime += 1;
else if (activeCategory === "Idle") idleTime += 1;
else if (activeCategory === "Production") prodTime += 1;

if (activeCategories.length === 1) {
  runningHour += 1;
}

await asset.set(setupPath, setupTime);
await asset.set(idlePath, idleTime);
await asset.set(prodPath, prodTime);
await asset.set(runningHourPath, runningHour);

send(msg);

const setupTime = Number(SetupDurationSec?.value ?? 0);
const idleTime = Number(IdleDurationSec?.value ?? 0);
const prodTime = Number(ProductionDurationSec?.value ?? 0);
const availabilityPath = Availability?.path ?? "";

if (!availabilityPath) {
  send(msg);
  return;
}

const totalTime = setupTime + idleTime + prodTime;
let availability = 0;
if (totalTime > 0 && Number.isFinite(totalTime)) {
  availability = (prodTime / totalTime) * 100;
}

availability = Number(Math.max(0, Math.min(100, availability)).toFixed(2));
await asset.set(availabilityPath, availability);

send(msg);

const actualSpeed = Number(MachineSpeed?.value ?? 0);
const idealSpeed = Number(IdealSpeed?.value ?? 0);
const performancePath = Performance?.path ?? "";

if (!performancePath) {
  send(msg);
  return;
}

let performance = 0;
if (idealSpeed > 0 && Number.isFinite(actualSpeed) && Number.isFinite(idealSpeed)) {
  performance = (actualSpeed / idealSpeed) * 100;
}

performance = Number(Math.max(0, Math.min(100, performance)).toFixed(2));
await asset.set(performancePath, performance);

send(msg);

const goodCount = Number(ProductGoodCount?.value ?? 0);
const rejectCount = Number(ProductRejectCount?.value ?? 0);
const productTotalCount = Number(ProductTotalCount?.value ?? 0);
const qualityPath = Quality?.path ?? "";

if (!qualityPath) {
  send(msg);
  return;
}

let totalProduced = goodCount + rejectCount;
if (!(totalProduced > 0) && productTotalCount > 0) {
  totalProduced = productTotalCount;
}

let quality = 0;
if (totalProduced > 0 && Number.isFinite(totalProduced)) {
  quality = (goodCount / totalProduced) * 100;
}

quality = Number(Math.max(0, Math.min(100, quality)).toFixed(2));
await asset.set(qualityPath, quality);

send(msg);

const availability = Number(Availability?.value ?? 0);
const performance = Number(Performance?.value ?? 0);
const quality = Number(Quality?.value ?? 0);
const oeePath = OEE?.path ?? "";

if (!oeePath) {
  send(msg);
  return;
}

let oee = 0;
if (Number.isFinite(availability) && Number.isFinite(performance) && Number.isFinite(quality)) {
  oee = (availability / 100) * (performance / 100) * (quality / 100) * 100;
}

oee = Number(Math.max(0, Math.min(100, oee)).toFixed(2));
await asset.set(oeePath, oee);

send(msg);

const lifecycle = String(msg.payload?.value ?? "").trim().toLowerCase();
const workOrder = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Work Order", "") ?? "").trim();
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Lifecycle Alarm";
const jobProgressRaw = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Job Progress", "") ?? "").trim();
const jobProgress = Number(jobProgressRaw.replace("%", "").trim());

if (!["load", "unload", "complete"].includes(lifecycle)) {
  return;
}

if (!workOrder || workOrder === "-") {
  await asset.set(alarmPath, "!!!No Active Work Order!!!");
  return;
}

if (lifecycle === "load") {
  await asset.setMany([
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Paper Consumed Setup", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Paper Consumed Idle", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Paper Consumed Production", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Total Paper Waste", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Total Paper Consumed", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Total Setup Time", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Total Idle Time", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Total Production Time", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Availability", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Performance", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.Quality", value: 0 },
    { path: "Jasuindo.OffsetPrinter.Taiyo1.OEE", value: 0 },
  ]);

  await asset.set(alarmPath, "-");

  msg.eventRequest = {
    mode: "open",
    notes: `${workOrder} lifecycle run opened`
  };

  send(msg, "open");
  return;
}

// if (isNaN(jobProgress) || jobProgress !== 100) {
//   await asset.set(alarmPath, "Your job progress must be exactly 100% before closing the event.");
//   await asset.set("Jasuindo.OffsetPrinter.Taiyo1.Job Lifecycle", "load");
//   return;
// }

await asset.set(alarmPath, "-");

msg.eventRequest = {
  mode: "close",
  notes: `${workOrder} lifecycle ${lifecycle}`
};

send(msg, "close");

const rawActivity = String(msg.payload?.value ?? "").trim();
const workOrder = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Work Order", "") ?? "").trim();
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Alarm";

if (!rawActivity || rawActivity === "-") {
  await asset.set(alarmPath, "-");
  return;
}

if (!workOrder || workOrder === "-") {
  await asset.set(alarmPath, "!!!No Active Work Order!!!");
  return;
}

const parts = rawActivity.split("/").map((item) => item.trim()).filter(Boolean);
const categoryToken = String(parts[0] || "").toLowerCase();
const activityDetail = parts.slice(1).join("/").trim() || "Run";

let templateId = "";

switch (categoryToken) {
  case "production":
    templateId = "template.taiyo.job.activity.production";
    break;
  case "setup":
    templateId = "template.taiyo.job.activity.setup";
    break;
  case "idle":
    templateId = "template.taiyo.job.activity.idle";
    break;
  default:
    await asset.set(alarmPath, `!!!Unknown activity category: ${rawActivity}!!!`);
    return;
}

await asset.set(alarmPath, "-");

msg.eventRequest = {
  mode: "open",
  templateId,
  vars: { activityDetail },
  notes: `${workOrder} ${categoryToken}/${activityDetail} opened`
};

send(msg);

const workOrder = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Work Order", "") ?? "").trim();
const lifecycle = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Job Lifecycle", "") ?? "").trim().toLowerCase();
const targetRaw = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Count Target", "") ?? "").trim();
const totalCount = Number(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Total Count", 0) ?? 0);
const productCountPerBook = Number(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Count Per Book", 0) ?? 0);
const progressPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Progress";

if (!workOrder || workOrder === "-" || !["load", "unload", "complete"].includes(lifecycle)) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const normalizedTarget = targetRaw.replace(/,/g, "").replace(/\s+/g, " ").trim();
const targetMatch = normalizedTarget.match(/^(-?\d+(?:\.\d+)?)\s*([A-Za-z]+)?$/);

if (!targetMatch) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const targetValue = Number(targetMatch[1]);
const targetUnit = String(targetMatch[2] || "EA").toUpperCase();

let targetEa = 0;
if (targetUnit === "EA") {
  targetEa = targetValue;
} else if (targetUnit === "BK") {
  targetEa = targetValue * productCountPerBook;
}

if (!Number.isFinite(targetEa) || targetEa <= 0) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const safeTotalCount = Number.isFinite(totalCount) ? totalCount : 0;
const progress = Math.max(0, Math.round((safeTotalCount / targetEa) * 100));

await asset.set(progressPath, progress);

send(msg);

await asset.setMany([
  { path: "Jasuindo.OffsetPrinter.Taiyo1.Job Progress", value: 0 },
  { path: "Jasuindo.OffsetPrinter.Taiyo1.Work Order", value: '-' },
  { path: "Jasuindo.OffsetPrinter.Taiyo1.Job Activity", value: '-' },
  { path: "Jasuindo.OffsetPrinter.Taiyo1.Job Lifecycle", value: '-' },
]);

send(msg);

scriptTemplates.script:
// ini adalah template script

helpers.log("----variable binding----")

helpers.log(binding_1)
helpers.log(JSON.stringify(binding_2.value));

const nowTs = msg.ts || helpers.now();

const eventPath = `${MachineAlarmAttribute.path}/Event/Alarm/MachineSpeedHigh`;
const speed = Number(MachinePresentValue?.value ?? 0);
const threshold = Number(Threshold ?? 0);
const operatorLabel = OperatorName?.value?.label ?? "-";

const openRows = await eventSys.get(`${eventPath}*`, "*", "*", "open", {}, { limit: 1 });

if (speed > threshold) {

  asset.set(MachineAlarmAttribute.path, `Oii ${operatorLabel} bahaya!`);

  if (openRows.length === 0) {
    await eventSys.open(eventPath,nowTs,{operatorLabel,speed,threshold},`Machine speed ${speed} > threshold ${threshold}`,"low",{ speed, threshold, operatorLabel, state: "open" });
  }

} else {

  asset.set(MachineAlarmAttribute.path, "No alarm.");

  if (openRows.length > 0) {
    await eventSys.close(`${eventPath}*`,nowTs,`Machine speed ${speed} <= threshold ${threshold}`,{ speed, threshold, operatorLabel, state: "close" });
  }
}

send(msg);

// VARIABLE BINDINGS
const jobLifecycleAttribute = JobLifecycleAttribute?.value || "-";
const workOrderAttribute = WorkOrderAttribute?.value || "-";
const operatorAttribute = OperatorAttribute?.value || "-";
const timestamp = Timestamp?.value || helpers.now();
const assetPath = AssetPath || "-";
const alarmAttributePath = AlarmAttribute?.path || "-";
const jobLifecycleAttributePath = JobLifecycleAttribute?.path || "-";
const jobActivityAttributePath = JobActivityAttribute?.path || "-";
const workOrderAttributePath = WorkOrderAttribute?.path || "-";
const jobProgressRaw = String(JobProgressAttribute?.value ?? "").trim();
const jobProgress = Number(jobProgressRaw.replace("%", "").trim());

const renderPath = (template, vars = {}) => {
  return String(template || "")
    .replaceAll("{assetPath}", String(vars.assetPath ?? assetPath))
    .replaceAll("{workOrder}", String(vars.workOrder ?? workOrderAttribute))
    .replaceAll("{activity}", String(vars.activity ?? "*"));
};

const lifecycleValue = String(jobLifecycleAttribute).trim().toLowerCase();
const lifecycleRunningEventPath = renderPath(LifecycleRunningEventPathTemplate);
const openedEvents = await eventSys.get(lifecycleRunningEventPath, "*", "*", "open", {}, { limit: 1 });
const templateVars = {
  assetPath,
  workOrder: workOrderAttribute,
  operator: operatorAttribute,
  timestamp
};

helpers.log("event mulai:", jobLifecycleAttribute);

if (!["load", "unload", "complete"].includes(lifecycleValue)) {
  helpers.log("--- bukan load/unload");
  return;
}

helpers.log("--- terdeteksi load/unload");

if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {
  asset.set(alarmAttributePath, "!!!Work order is empty!!!");
  asset.set(jobLifecycleAttributePath, "-");
  msg.payload = "alarm: work order is empty";
  send(msg);
  return;
}

if (lifecycleValue !== "load" && (isNaN(jobProgress) || jobProgress !== 100)) {
  asset.set(alarmAttributePath, "Your job progress must be exactly 100% before closing the event.");
  asset.set(jobLifecycleAttributePath, "load");
  msg.payload = "alarm: job progress must be exactly 100 before close";
  send(msg);
  return;
}

asset.set(alarmAttributePath, "-");

if (lifecycleValue === "load") {
  if (openedEvents.length === 0) {
    asset.setMany(
      [
        { path: PaperConsumedIdle.path, value: 0 },
        { path: PaperConsumedProduction.path, value: 0 },
        { path: PaperConsumedSetup.path, value: 0 },
        { path: TotalIdleTime.path, value: 0 },
        { path: TotalProductionTime.path, value: 0 },
        { path: TotalSetupTime.path, value: 0 },
        { path: JobActivityCategoryAttribute.path, value: "-" }
      ]
    );

    await eventSys.openTemplate("job_lifecycle_running", {
      vars: templateVars,
      notes: `${workOrderAttribute} loaded`
    });

    msg.payload = "event opened";
    send(msg);
  }
} else if (lifecycleValue === "unload") {
  if (openedEvents.length > 0) {
    await eventSys.closeTemplate("job_lifecycle_running", {
      vars: templateVars,
      notes: `${workOrderAttribute} unloaded`
    });

    await eventSys.closeTemplate("job_activity", {
      vars: { ...templateVars, activity: "*" },
      notes: `${workOrderAttribute} unloaded`
    });

    asset.set(workOrderAttributePath, "-");
    asset.set(jobLifecycleAttributePath, "-");
    asset.set(jobActivityAttributePath, "-");
    asset.set(JobActivityCategoryAttribute.path, "-");

    msg.payload = "event closed";
    send(msg);
  }
} else if (lifecycleValue === "complete") {
  if (openedEvents.length > 0) {
    await eventSys.closeTemplate("job_lifecycle_running", {
      vars: templateVars,
      notes: `${workOrderAttribute} completed`
    });

    await eventSys.closeTemplate("job_activity", {
      vars: { ...templateVars, activity: "*" },
      notes: `${workOrderAttribute} completed`
    });

    asset.set(workOrderAttributePath, "-");
    asset.set(jobLifecycleAttributePath, "-");
    asset.set(jobActivityAttributePath, "-");

    msg.payload = "event closed";
    send(msg);
  }
}

return;

// VARIABLE BINDINGS
const jobActivityAttribute = JobActivityAttribute?.value || "-";
const jobActivityCategoryAttributePath = JobActivityCategoryAttribute?.path || "-";
const workOrderAttribute = WorkOrderAttribute?.value || "-";
const operatorAttribute = OperatorAttribute?.value || "-";
const timestamp = Timestamp?.value || helpers.now();
const assetPath = AssetPath || "-";
const alarmAttributePath = AlarmAttribute?.path || "-";
const materialBarcode = MaterialBarcode?.value || "-";

const renderPath = (template, vars = {}) => {
  return String(template || "")
    .replaceAll("{assetPath}", String(vars.assetPath ?? assetPath))
    .replaceAll("{workOrder}", String(vars.workOrder ?? workOrderAttribute))
    .replaceAll("{activity}", String(vars.activity ?? "*"));
};

if (jobActivityAttribute === "-" || jobActivityAttribute === "" || jobActivityAttribute === null) {
  asset.set(jobActivityCategoryAttributePath, "-");
  send(msg);
  return;
}

if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {
  asset.set(alarmAttributePath, "!!!No Active Work Order!!!");
  asset.set(jobActivityCategoryAttributePath, "-");
  send(msg);
  return;
}

const rawActivity = String(jobActivityAttribute).trim();
const activityLower = rawActivity.toLowerCase();

let activityType = "-";
if (activityLower === "production" || activityLower.startsWith("production/")) {
  activityType = "Production";
} else if (activityLower === "setup" || activityLower.startsWith("setup/")) {
  activityType = "Setup";
} else if (activityLower === "idle" || activityLower.startsWith("idle/")) {
  activityType = "Idle";
} else {
  asset.set(alarmAttributePath, `!!!Unknown activity type: ${rawActivity}!!!`);
  asset.set(jobActivityCategoryAttributePath, "-");
  send(msg);
  return;
}

asset.set(jobActivityCategoryAttributePath, activityType);

const eventPath = renderPath(JobActivityEventPathTemplate, { activity: rawActivity });
const openedExact = await eventSys.get(eventPath, "*", "*", "open", {}, { limit: 1 });
if (openedExact.length > 0) {
  asset.set(alarmAttributePath, `!!!Activity already open: ${rawActivity}!!!`);
  send(msg);
  return;
}

const templateBase = {
  assetPath,
  workOrder: workOrderAttribute,
  operator: operatorAttribute,
  timestamp,
  materialBarcode,
  activityType
};

if (activityType === "Production") {
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Setup/*" },
    notes: "auto close by Production transition"
  });
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Idle/*" },
    notes: "auto close by Production transition"
  });
} else if (activityType === "Setup") {
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Production/*" },
    notes: "auto close by Setup transition"
  });
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Idle/*" },
    notes: "auto close by Setup transition"
  });
} else if (activityType === "Idle") {
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Production/*" },
    notes: "auto close by Idle transition"
  });
  await eventSys.closeTemplate("job_activity", {
    vars: { ...templateBase, activity: "Setup/*" },
    notes: "auto close by Idle transition"
  });
}

asset.set(alarmAttributePath, "-");

await eventSys.openTemplate("job_activity", {
  vars: { ...templateBase, activity: rawActivity },
  notes: `activity ${rawActivity} created`
});

send(msg);

const raw = Number(EncoderRawValue?.value || 0);
const paperPath = PaperLength?.path || "";
const prevRawPath = EncoderPrevRaw?.path || "";

if (!paperPath || !prevRawPath) {
  send(msg);
  return;
}

const prevRaw = Number(EncoderPrevRaw?.value || 0);

// naik normal -> delta selisih
// turun/reset -> delta = raw (anggap restart dari 0, tapi mungkin kebaca telat dan langsung lompat)
const delta = raw >= prevRaw ? (raw - prevRaw) : raw;

const total = Number(PaperLength?.value || 0) + delta;

asset.set(paperPath, total);
asset.set(prevRawPath, raw);

send(msg);

const paperConsumedProduction = Number(PaperConsumedProduction?.value ?? 0);
const productFoldLength = Number(ProductFoldLength?.value ?? 0);
const productPerFold = Number(ProductPerFold?.value ?? 0);
const productTotalCountPath = ProductTotalCount?.path ?? "";

if (!productTotalCountPath) {
  send(msg);
  return;
}

let productTotalCount = 0;
if (productFoldLength > 0 && productPerFold > 0) {
  productTotalCount = (paperConsumedProduction / productFoldLength) * productPerFold;
}

productTotalCount = Number(productTotalCount.toFixed(2));

await asset.set(productTotalCountPath, productTotalCount);

msg.payload = { productTotalCount, paperConsumedProduction, productFoldLength, productPerFold };

send(msg);

const raw = Number(EncoderRawValue?.value ?? 0);
const prevRaw = Number(EncoderPrevRaw?.value ?? 0);
const prevRawPath = EncoderPrevRaw?.path ?? "";
const machineSpeedPath = MachineSpeed?.path ?? "";
const setupPath = PaperConsumedSetup?.path ?? "";
const idlePath = PaperConsumedIdle?.path ?? "";
const prodPath = PaperConsumedProduction?.path ?? "";
const wastePath = PaperWaste?.path ?? "";
const totalConsumedPath = PaperTotalConsumed?.path ?? "";
const workOrderPath = "Jasuindo.OffsetPrinter.Taiyo1.Work Order";
const categoryPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Category";
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Alarm";
const assetPath = "Jasuindo.OffsetPrinter.Taiyo1";
const workOrder = String(asset.get(workOrderPath, "") ?? "").trim();

if (!prevRawPath) {
  send(msg);
  return;
}

const delta = raw >= prevRaw ? (raw - prevRaw) : raw;
if (!Number.isFinite(delta) || delta < 0) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

const speedMpm = delta * 0.6;
if (machineSpeedPath) {
  await asset.set(machineSpeedPath, speedMpm);
}

let activeCategory = "-";
let activeCategories = [];

if (workOrder && workOrder !== "-") {
  const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

if (delta === 0 || activeCategories.length !== 1) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

const setupPrev = Number(PaperConsumedSetup?.value ?? 0);
const idlePrev = Number(PaperConsumedIdle?.value ?? 0);
const prodPrev = Number(PaperConsumedProduction?.value ?? 0);

let setupNew = setupPrev;
let idleNew = idlePrev;
let prodNew = prodPrev;

if (activeCategory === "Setup") setupNew += delta / 100;
else if (activeCategory === "Idle") idleNew += delta / 100;
else if (activeCategory === "Production") prodNew += delta / 100;

if (setupPath) await asset.set(setupPath, setupNew);
if (idlePath) await asset.set(idlePath, idleNew);
if (prodPath) await asset.set(prodPath, prodNew);

const waste = setupNew + idleNew;
const totalConsumed = waste + prodNew;

if (wastePath) await asset.set(wastePath, waste);
if (totalConsumedPath) await asset.set(totalConsumedPath, totalConsumed);

await asset.set(prevRawPath, raw);

send(msg);

// VARIABLE BINDINGS
const workOrderAttribute = WorkOrderAttribute?.value || "-";
const assetPath = AssetPath || "-";

// STOP jika WO invalid
if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {
  helpers.log("[ActivityDetector] skip: work order empty");
  send(msg);
  return;
}

// BASE PATH activity
const base = `${assetPath}/Job/${workOrderAttribute}/Activity`;

// PATTERN yang mau dicek (status open)
const setupPattern = `${base}/Setup/*`;
const productionPattern = `${base}/Production`;
const idlePattern = `${base}/Idle/*`;

// QUERY OPEN EVENTS
const setupOpen = await eventSys.get(setupPattern, "*", "*", "open", {}, { limit: 200 });
const productionOpen = await eventSys.get(productionPattern, "*", "*", "open", {}, { limit: 200 });
const idleOpen = await eventSys.get(idlePattern, "*", "*", "open", {}, { limit: 200 });

// GABUNG + DEDUPE by id
const dedup = new Map();
for (const row of [...setupOpen, ...productionOpen, ...idleOpen]) {
  if (!row?.id) continue;
  dedup.set(row.id, row);
}
const activeEvents = Array.from(dedup.values());

// LOG SUMMARY
helpers.log(`${helpers.now()} [ActivityDetector] active count:`, activeEvents.length);
helpers.log("[ActivityDetector] setup:", setupOpen.length, "production:", productionOpen.length, "idle:", idleOpen.length);

// LOG DETAIL path per event
// for (const ev of activeEvents) {
//   helpers.log("[ActivityDetector] active:", ev.event_path, "| status:", ev.status, "| start:", ev.start_ts);
// }

send(msg);

const setupPath = SetupDurationSec?.path ?? "";
const idlePath = IdleDurationSec?.path ?? "";
const prodPath = ProductionDurationSec?.path ?? "";
const runningHourPath = RunningHour?.path ?? "";
const workOrderPath = "Jasuindo.OffsetPrinter.Taiyo1.Work Order";
const categoryPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Category";
const alarmPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Activity Alarm";
const assetPath = "Jasuindo.OffsetPrinter.Taiyo1";
const workOrder = String(asset.get(workOrderPath, "") ?? "").trim();

if (!setupPath || !idlePath || !prodPath || !runningHourPath) {
  send(msg);
  return;
}

let setupTime = Number(SetupDurationSec?.value ?? 0);
let idleTime = Number(IdleDurationSec?.value ?? 0);
let prodTime = Number(ProductionDurationSec?.value ?? 0);
let runningHour = Number(RunningHour?.value ?? 0);

let activeCategory = "-";
let activeCategories = [];

if (workOrder && workOrder !== "-") {
  const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

if (activeCategory === "Setup") setupTime += 1;
else if (activeCategory === "Idle") idleTime += 1;
else if (activeCategory === "Production") prodTime += 1;

if (activeCategories.length === 1) {
  runningHour += 1;
}

await asset.set(setupPath, setupTime);
await asset.set(idlePath, idleTime);
await asset.set(prodPath, prodTime);
await asset.set(runningHourPath, runningHour);

send(msg);

const workOrder = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Work Order", "") ?? "").trim();
const lifecycle = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Job Lifecycle", "") ?? "").trim().toLowerCase();
const targetRaw = String(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Count Target", "") ?? "").trim();
const totalCount = Number(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Total Count", 0) ?? 0);
const productCountPerBook = Number(asset.get("Jasuindo.OffsetPrinter.Taiyo1.Product Count Per Book", 0) ?? 0);
const progressPath = "Jasuindo.OffsetPrinter.Taiyo1.Job Progress";

if (!workOrder || workOrder === "-" || !["load", "unload", "complete"].includes(lifecycle)) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const normalizedTarget = targetRaw.replace(/,/g, "").replace(/\s+/g, " ").trim();
const targetMatch = normalizedTarget.match(/^(-?\d+(?:\.\d+)?)\s*([A-Za-z]+)?$/);

if (!targetMatch) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const targetValue = Number(targetMatch[1]);
const targetUnit = String(targetMatch[2] || "EA").toUpperCase();

let targetEa = 0;
if (targetUnit === "EA") {
  targetEa = targetValue;
} else if (targetUnit === "BK") {
  targetEa = targetValue * productCountPerBook;
}

if (!Number.isFinite(targetEa) || targetEa <= 0) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const safeTotalCount = Number.isFinite(totalCount) ? totalCount : 0;
const progress = Math.max(0, Math.round((safeTotalCount / targetEa) * 100));

await asset.set(progressPath, progress);

send(msg);
